import type { StateDeltaEvent, SubgraphSlice } from '@schema';
import { CelestialCalendarEngine } from './consistency/CelestialCalendarEngine.js';
import { NarrativeGraph } from './consistency/NarrativeGraph.js';

export class WorldOntologyEngine {
  private deltas: StateDeltaEvent[] = [];
  private narrativeGraph = new NarrativeGraph();

  applyDelta(event: StateDeltaEvent): void {
    this.deltas.push(event);
  }

  getNarrativeGraph(): NarrativeGraph {
    return this.narrativeGraph;
  }

  exportSlice(rootNodeId: string): SubgraphSlice {
    return {
      id: `slice-${Date.now()}`,
      rootNodeId,
      depth: 1,
      nodes: {},
      edges: [],
      version: 1,
    };
  }
}

export * from './consistency/AhoCorasickAutomaton.js';
export * from './consistency/CelestialCalendarEngine.js';
export * from './consistency/NarrativeGraph.js';
